const raw = $json.body ?? $json;
const aliases = {
  promptlab: 'promptlab',
  'promptlab.ai': 'promptlab',
  promptlive: 'promptlab',
  proptlive: 'promptlab',
  zelovita: 'zelovita'
};
const brandKey = String(raw.brand ?? '').trim().toLowerCase();
const brand = aliases[brandKey];
if (!brand) throw new Error('brand deve ser promptlab ou zelovita');
const topic = String(raw.topic ?? '').trim();
if (topic.length < 3) throw new Error('topic é obrigatório');
const allowedPlatforms = ['instagram', 'facebook', 'tiktok'];
const requested = Array.isArray(raw.platforms) && raw.platforms.length ? raw.platforms : allowedPlatforms;
const platforms = [...new Set(requested.map(v => String(v).toLowerCase()))];
if (platforms.some(v => !allowedPlatforms.includes(v))) throw new Error('plataforma inválida');
const requestId = String(raw.request_id ?? `social-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
return [{ json: {
  request_id: requestId,
  brand,
  topic,
  objective: String(raw.objective ?? ''),
  audience: String(raw.audience ?? ''),
  platforms,
  format: String(raw.format ?? 'feed'),
  source_urls: Array.isArray(raw.source_urls) ? raw.source_urls : [],
  affiliate_url: raw.affiliate_url ?? null,
  notes: String(raw.notes ?? ''),
  language: 'pt-BR'
} }];

const dify = $json;
const original = $('Normalizar e validar').first().json;
if (dify?.data?.status && dify.data.status !== 'succeeded') {
  throw new Error(`Dify falhou: ${dify.data.error || dify.data.status}`);
}
let result = dify?.data?.outputs?.result ?? dify?.data?.outputs?.output ?? dify?.data?.outputs;
if (typeof result === 'string') {
  const cleaned = result.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try { result = JSON.parse(cleaned); } catch { throw new Error('Dify não retornou JSON válido'); }
}
if (!result || typeof result !== 'object') throw new Error('Dify não retornou um objeto');
if (!Array.isArray(result.channels) || result.channels.length === 0) throw new Error('Dify não retornou channels');
const channels = result.channels.map(channel => ({
  ...channel,
  platform: String(channel.platform || '').toLowerCase(),
  provider_integration_id: null,
  media_status: channel.media_status || 'pending',
  media: Array.isArray(channel.media) ? channel.media : []
}));
return [{ json: {
  ...result,
  request_id: original.request_id,
  brand: original.brand,
  topic: original.topic,
  language: 'pt-BR',
  source_urls: original.source_urls,
  affiliate_url: original.affiliate_url,
  approval_status: 'pending',
  approved: false,
  channels,
  generation: {
    provider: 'dify',
    workflow_run_id: dify.workflow_run_id || dify?.data?.id || null,
    generated_at: new Date().toISOString()
  }
} }];
